card.statement:
The generic double affine Hecke algebra $\bH(R)$ is the $\F$-algebra generated by the affine Hecke algebra $\mathcal{H}(R)$, the lattice $\Q_X$ such that the following relations, called Bernstein-Lusztig relations, are satisfied for all $\b\in Q^\vee$:

For $R$ of type $X_n^{(1)}\neq C_n^{(1)}$, $n\geq 1$

\begin{subequations}
\begin{alignat}{2}
& T_iX_\b-X_{s_i(\b)} T_i = (t_{i}^{\frac{1}{2}}-t_{i}^{-\frac{1}{2}} )\frac{X_\b-X_{s_i(\b)}}{1-X_{-\a_i^\vee}}, \quad 1\leq i\leq n, \\
& T_0X_\b-X_{s_0(\b)} T_0 = (t_{01}^{\frac{1}{2}}-t_{01}^{-\frac{1}{2}} )\frac{X_\b-X_{s_0(\b)}}{1-X_{-\a_0^\vee}};
\end{alignat}
\end{subequations}

For $R$ of type $C_n^{(1)}$, $n\geq 1$

\begin{subequations}
\begin{alignat}{2}
& T_iX_\b-X_{s_i(\b)} T_i = (t_{i}^{\frac{1}{2}}-t_{i}^{-\frac{1}{2}} )\frac{X_\b-X_{s_i(\b)}}{1-X_{-\a_i^\vee}}, \quad 1\leq i\leq n-1,  \\
& T_nX_\b-X_{s_n(\b)} T_n = \left((t_{n}^{\frac{1}{2}}-t_{n}^{-\frac{1}{2}}) +(t_{03}^{\frac{1}{2}}-t_{03}^{-\frac{1}{2}})X_{-\a_n^\vee} \right)\frac{X_\b-X_{s_n(\b)}}{1-X_{-2\a_n^\vee}}, \\
& T_0X_\b-X_{s_0(\b)} T_0 = \left((t_{01}^{\frac{1}{2}}-t_{01}^{-\frac{1}{2}}) +(t_{02}^{\frac{1}{2}}-t_{02}^{-\frac{1}{2}})X_{-\a_0^\vee} \right)\frac{X_\b-X_{s_0(\b)}}{1-X_{-2\a_0^\vee}} ;
\end{alignat}
\end{subequations}

For $R$ of type $D_{n+1}^{(2)}$, $n\geq 3$, $E_6^{(2)}$, $D_4^{(3)}$

\begin{subequations}
\begin{alignat}{2}
& T_iX_\b-X_{s_i(\b)} T_i = (t_{i}^{\frac{1}{2}}-t_{i}^{-\frac{1}{2}} )\frac{X_\b-X_{s_i(\b)}}{1-X_{-\a_i^\vee}}, \quad 1\leq i\leq n, \\
& T_0X_\b-X_{s_0(\b)} T_0 = (\th_{0}^{\frac{1}{2}}-\th_{0}^{-\frac{1}{2}} )\frac{X_\b-X_{s_0(\b)}}{1-X_{-\a_0^\vee}};
\end{alignat}
\end{subequations}

For $R$ of type $A_{n}^{(2)}$, $n\geq 2$

\begin{subequations}
\begin{alignat}{2}
& T_iX_\b-X_{s_i(\b)} T_i = (t_{i}^{\frac{1}{2}}-t_{i}^{-\frac{1}{2}} )\frac{X_\b-X_{s_i(\b)}}{1-X_{-\a_i^\vee}}, \quad 1\leq i\leq n-1, \\
& T_nX_\b-X_{s_n(\b)} T_n = \left((t_{n}^{\frac{1}{2}}-t_{n}^{-\frac{1}{2}}) +(\phi_{0}^{\frac{1}{2}}-\phi_{0}^{-\frac{1}{2}})X_{-\a_n^\vee} \right)\frac{X_\b-X_{s_n(\b)}}{1-X_{-2\a_n^\vee}}, \\
& T_0X_\b-X_{s_0(\b)} T_0 = (\th_{0}^{\frac{1}{2}}-\th_{0}^{-\frac{1}{2}} )\frac{X_\b-X_{s_0(\b)}}{1-X_{-\a_0^\vee}};
\end{alignat}
\end{subequations}

For $R$ of type $D_3^{(2)}$

\begin{subequations}
\begin{alignat}{2}
& T_1X_\b-X_{s_1(\b)} T_1 = \left((t_{1}^{\frac{1}{2}}-t_{1}^{-\frac{1}{2}}) +(\phi_{0}^{\frac{1}{2}}-\phi_{0}^{-\frac{1}{2}})X_{-\a_1^\vee} \right)\frac{X_\b-X_{s_1(\b)}}{1-X_{-2\a_1^\vee}}, \\
& T_2X_\b-X_{s_2(\b)} T_i = (t_{2}^{\frac{1}{2}}-t_{2}^{-\frac{1}{2}} )\frac{X_\b-X_{s_2(\b)}}{1-X_{-\a_2^\vee}}, \\
& T_0X_\b-X_{s_0(\b)} T_0 = (\th_{0}^{\frac{1}{2}}-\th_{0}^{-\frac{1}{2}} )\frac{X_\b-X_{s_0(\b)}}{1-X_{-\a_0^\vee}}.
\end{alignat}
\end{subequations}
